package org.apache.lucene.queryparser.classic;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.apache.lucene.analysis.Analyzer;
import org.apache.lucene.search.BooleanClause;
import org.apache.lucene.search.BooleanQuery;
import org.apache.lucene.search.BoostQuery;
import org.apache.lucene.search.MultiPhraseQuery;
import org.apache.lucene.search.PhraseQuery;
import org.apache.lucene.search.Query;
import java.io.IOException;
import org.apache.lucene.analysis.TokenStream;
import org.apache.lucene.analysis.tokenattributes.TermToBytesRefAttribute;
import org.apache.lucene.index.Term;
import org.apache.lucene.queries.spans.SpanNearQuery;
import org.apache.lucene.queries.spans.SpanNotQuery;
import org.apache.lucene.queries.spans.SpanOrQuery;
import org.apache.lucene.queries.spans.SpanQuery;
import org.apache.lucene.queries.spans.SpanTermQuery;
import org.apache.lucene.queryparser.simple.SimpleQueryParser;
import org.apache.lucene.queryparser.xml.DOMUtils;
import org.apache.lucene.queryparser.xml.ParserException;
import org.apache.lucene.search.BooleanClause.Occur;
import org.apache.lucene.search.DisjunctionMaxQuery;
import org.apache.lucene.search.FuzzyQuery;
import org.apache.lucene.search.IndexSearcher;
import org.apache.lucene.search.MatchAllDocsQuery;
import org.apache.lucene.search.MatchNoDocsQuery;
import org.apache.lucene.search.MultiTermQuery;
import org.apache.lucene.search.PrefixQuery;
import org.apache.lucene.search.SynonymQuery;
import org.apache.lucene.search.TermQuery;
import org.apache.lucene.search.TermRangeQuery;
import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.automaton.LevenshteinAutomata;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

/** A QueryParser which constructs queries to search multiple fields. */
public class MultiFieldQueryParser extends QueryParser {
  protected String[] fields;
  protected Map<String, Float> boosts;

  private Map<String, Float> simpleWeights;
  private int simpleFlags;
  private BooleanClause.Occur simpleDefaultOperator;
  private Analyzer simpleAnalyzer;
  private SimpleSyntaxState simpleParseState;

  private String phraseField;
  private String phraseQueryText;
  private int phraseSlop;
  private boolean phraseInOrder;
  private Query phraseContents;

  private org.apache.lucene.queryparser.xml.QueryBuilder xmlFactory;
  private Analyzer xmlAnalyzer;
  private float xmlBoost;
  private int xmlMinShouldMatch;
  private float xmlTieBreaker;

  private int analysisMode;
  private int analysisCount;
  private String analysisField;
  private Query analysisQuery;

  /**
   * Creates a MultiFieldQueryParser. Allows passing of a map with term to Boost, and the boost to
   * apply to each term.
   *
   * <p>It will, when parse(String query) is called, construct a query like this (assuming the query
   * consists of two terms and you specify the two fields <code>title</code> and <code>body</code>):
   * <code>
   * (title:term1 body:term1) (title:term2 body:term2)
   * </code>
   *
   * <p>When setDefaultOperator(AND_OPERATOR) is set, the result will be: <code>
   * +(title:term1 body:term1) +(title:term2 body:term2)
   * </code>
   *
   * <p>When you pass a boost (title=&gt;5 body=&gt;10) you can get <code>
   * +(title:term1^5.0 body:term1^10.0) +(title:term2^5.0 body:term2^10.0)
   * </code>
   *
   * <p>In other words, all the query's terms must appear, but it doesn't matter in what fields they
   * appear.
   */
  public MultiFieldQueryParser(String[] fields, Analyzer analyzer, Map<String, Float> boosts) {
    this(fields, analyzer);
    this.boosts = boosts;
  }

  /**
   * Creates a MultiFieldQueryParser.
   *
   * <p>It will, when parse(String query) is called, construct a query like this (assuming the query
   * consists of two terms and you specify the two fields <code>title</code> and <code>body</code>):
   * <code>
   * (title:term1 body:term1) (title:term2 body:term2)
   * </code>
   *
   * <p>When setDefaultOperator(AND_OPERATOR) is set, the result will be: <code>
   * +(title:term1 body:term1) +(title:term2 body:term2)
   * </code>
   *
   * <p>In other words, all the query's terms must appear, but it doesn't matter in what fields they
   * appear.
   */
  public MultiFieldQueryParser(String[] fields, Analyzer analyzer) {
    super(null, analyzer);
    this.fields = fields;
  }

  @Override
  protected Query getFieldQuery(String field, String queryText, int slop) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        Query q = super.getFieldQuery(fields[i], queryText, true);
        if (q != null) {
          q = applyMappedBoost(q, fields[i]);
          q = applySlop(q, slop);
          clauses.add(q);
        }
      }
      if (clauses.size() == 0) // happens for stopwords
      return null;
      return getMultiFieldQuery(clauses);
    }
    Query q = super.getFieldQuery(field, queryText, true);
    q = applySlop(q, slop);
    return q;
  }

  private Query applySlop(Query q, int slop) {
    if (q instanceof PhraseQuery) {
      PhraseQuery.Builder builder = new PhraseQuery.Builder();
      builder.setSlop(slop);
      PhraseQuery pq = (PhraseQuery) q;
      org.apache.lucene.index.Term[] terms = pq.getTerms();
      int[] positions = pq.getPositions();
      for (int i = 0; i < terms.length; ++i) {
        builder.add(terms[i], positions[i]);
      }
      q = builder.build();
    } else if (q instanceof MultiPhraseQuery) {
      MultiPhraseQuery mpq = (MultiPhraseQuery) q;

      if (slop != mpq.getSlop()) {
        q = new MultiPhraseQuery.Builder(mpq).setSlop(slop).build();
      }
    }
    return q;
  }

  @Override
  protected Query getFieldQuery(String field, String queryText, boolean quoted)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      Query[] fieldQueries = new Query[fields.length];
      int maxTerms = 0;
      for (int i = 0; i < fields.length; i++) {
        Query q = super.getFieldQuery(fields[i], queryText, quoted);
        if (q != null) {
          if (q instanceof BooleanQuery) {
            maxTerms = Math.max(maxTerms, ((BooleanQuery) q).clauses().size());
          } else {
            maxTerms = Math.max(1, maxTerms);
          }
          fieldQueries[i] = q;
        }
      }
      for (int termNum = 0; termNum < maxTerms; termNum++) {
        List<Query> termClauses = new ArrayList<>();
        for (int i = 0; i < fields.length; i++) {
          if (fieldQueries[i] != null) {
            Query q = null;
            if (fieldQueries[i] instanceof BooleanQuery) {
              List<BooleanClause> nestedClauses = ((BooleanQuery) fieldQueries[i]).clauses();
              if (termNum < nestedClauses.size()) {
                q = nestedClauses.get(termNum).getQuery();
              }
            } else if (termNum == 0) { // e.g. TermQuery-s
              q = fieldQueries[i];
            }
            if (q != null) {
              q = applyMappedBoost(q, fields[i]);
              termClauses.add(q);
            }
          }
        }
        if (maxTerms > 1) {
          if (termClauses.size() > 0) {
            BooleanQuery.Builder builder = newBooleanQuery();
            for (Query termClause : termClauses) {
              builder.add(termClause, BooleanClause.Occur.SHOULD);
            }
            clauses.add(builder.build());
          }
        } else {
          clauses.addAll(termClauses);
        }
      }
      if (clauses.size() == 0) // happens for stopwords
      return null;
      return getMultiFieldQuery(clauses);
    }
    Query q = super.getFieldQuery(field, queryText, quoted);
    return q;
  }

  @Override
  protected Query getFuzzyQuery(String field, String termStr, float minSimilarity)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getFuzzyQuery(fields[i], termStr, minSimilarity));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getFuzzyQuery(field, termStr, minSimilarity);
  }

  @Override
  protected Query getPrefixQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getPrefixQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getPrefixQuery(field, termStr);
  }

  @Override
  protected Query getWildcardQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getWildcardQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getWildcardQuery(field, termStr);
  }

  @Override
  protected Query getRangeQuery(
      String field, String part1, String part2, boolean startInclusive, boolean endInclusive)
      throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getRangeQuery(fields[i], part1, part2, startInclusive, endInclusive));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getRangeQuery(field, part1, part2, startInclusive, endInclusive);
  }

  @Override
  protected Query getRegexpQuery(String field, String termStr) throws ParseException {
    if (field == null) {
      List<Query> clauses = new ArrayList<>();
      for (int i = 0; i < fields.length; i++) {
        clauses.add(getRegexpQuery(fields[i], termStr));
      }
      return getMultiFieldQuery(clauses);
    }
    return super.getRegexpQuery(field, termStr);
  }

  /** Creates a multifield query */
  // TODO: investigate more general approach by default, e.g. DisjunctionMaxQuery?
  protected Query getMultiFieldQuery(List<Query> queries) throws ParseException {
    if (queries.isEmpty()) {
      return null; // all clause words were filtered away by the analyzer.
    }
    BooleanQuery.Builder query = newBooleanQuery();
    for (Query sub : queries) {
      query.add(sub, BooleanClause.Occur.SHOULD);
    }
    return query.build();
  }

  /**
   * Parses a query which searches on the fields specified.
   *
   * <p>If x fields are specified, this effectively constructs:
   *
   * <pre>
   * <code>
   * (field1:query1) (field2:query2) (field3:query3)...(fieldx:queryx)
   * </code>
   * </pre>
   *
   * @param queries Queries strings to parse
   * @param fields Fields to search on
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the queries array differs from the length of
   *     the fields array
   */
  public static Query parse(String[] queries, String[] fields, Analyzer analyzer)
      throws ParseException {
    if (queries.length != fields.length)
      throw new IllegalArgumentException("queries.length != fields.length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(queries[i]);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, BooleanClause.Occur.SHOULD);
      }
    }
    return bQuery.build();
  }

  /**
   * Parses a query, searching on the fields specified. Use this if you need to specify certain
   * fields as required, and others as prohibited.
   *
   * <p>Usage:
   *
   * <pre class="prettyprint">
   * <code>
   * String[] fields = {"filename", "contents", "description"};
   * BooleanClause.Occur[] flags = {BooleanClause.Occur.SHOULD,
   *                BooleanClause.Occur.MUST,
   *                BooleanClause.Occur.MUST_NOT};
   * MultiFieldQueryParser.parse("query", fields, flags, analyzer);
   * </code>
   * </pre>
   *
   * <p>The code above would construct a query:
   *
   * <pre>
   * <code>
   * (filename:query) +(contents:query) -(description:query)
   * </code>
   * </pre>
   *
   * @param query Query string to parse
   * @param fields Fields to search on
   * @param flags Flags describing the fields
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the fields array differs from the length of
   *     the flags array
   */
  public static Query parse(
      String query, String[] fields, BooleanClause.Occur[] flags, Analyzer analyzer)
      throws ParseException {
    if (fields.length != flags.length)
      throw new IllegalArgumentException("fields.length != flags.length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(query);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, flags[i]);
      }
    }
    return bQuery.build();
  }

  /**
   * Parses a query, searching on the fields specified. Use this if you need to specify certain
   * fields as required, and others as prohibited.
   *
   * <p>Usage:
   *
   * <pre class="prettyprint">
   * <code>
   * String[] query = {"query1", "query2", "query3"};
   * String[] fields = {"filename", "contents", "description"};
   * BooleanClause.Occur[] flags = {BooleanClause.Occur.SHOULD,
   *                BooleanClause.Occur.MUST,
   *                BooleanClause.Occur.MUST_NOT};
   * MultiFieldQueryParser.parse(query, fields, flags, analyzer);
   * </code>
   * </pre>
   *
   * <p>The code above would construct a query:
   *
   * <pre>
   * <code>
   * (filename:query1) +(contents:query2) -(description:query3)
   * </code>
   * </pre>
   *
   * @param queries Queries string to parse
   * @param fields Fields to search on
   * @param flags Flags describing the fields
   * @param analyzer Analyzer to use
   * @throws ParseException if query parsing fails
   * @throws IllegalArgumentException if the length of the queries, fields, and flags array differ
   */
  public static Query parse(
      String[] queries, String[] fields, BooleanClause.Occur[] flags, Analyzer analyzer)
      throws ParseException {
    if (!(queries.length == fields.length && queries.length == flags.length))
      throw new IllegalArgumentException(
          "queries, fields, and flags array have have different length");
    BooleanQuery.Builder bQuery = new BooleanQuery.Builder();
    for (int i = 0; i < fields.length; i++) {
      QueryParser qp = new QueryParser(fields[i], analyzer);
      Query q = qp.parse(queries[i]);
      if (q != null
          && // q never null, just being defensive
          (!(q instanceof BooleanQuery) || ((BooleanQuery) q).clauses().size() > 0)) {
        bQuery.add(q, flags[i]);
      }
    }
    return bQuery.build();
  }

  public void prepareSimpleParse(
      Map<String, Float> weights, int flags, BooleanClause.Occur operator) {
    this.simpleWeights = weights;
    this.simpleFlags = flags;
    this.simpleDefaultOperator = operator;
    this.simpleAnalyzer = getAnalyzer();
  }

  public Query parseSimpleSyntax(String queryText) {
    if ("*".equals(queryText.trim())) {
      return new MatchAllDocsQuery();
    }
    char[] data = queryText.toCharArray();
    char[] buffer = new char[data.length];
    SimpleSyntaxState state = new SimpleSyntaxState(data, buffer, 0, data.length);
    this.simpleParseState = state;
    parseSimpleSubQuery(state);
    if (state.top == null) {
      return new MatchNoDocsQuery("empty string passed to query parser");
    }
    return state.top;
  }

  private void parseSimpleSubQuery(SimpleSyntaxState state) {
    this.simpleParseState = state;
    while (simpleRemainingLength() > 0) {
      if (isSimpleSubQueryStart(state)) {
        consumeSimpleSubQuery(state);
      } else if (isSimpleSubQueryEnd(state)) {
        ++state.index;
      } else if (isSimplePhraseStart(state)) {
        consumeSimplePhrase(state);
      } else if (isSimpleAndOperator(state)) {
        if (state.currentOperation == null && state.top != null) {
          state.currentOperation = BooleanClause.Occur.MUST;
        }
        ++state.index;
      } else if (isSimpleOrOperator(state)) {
        if (state.currentOperation == null && state.top != null) {
          state.currentOperation = BooleanClause.Occur.SHOULD;
        }
        ++state.index;
      } else if (isSimpleNotOperator(state)) {
        ++state.not;
        ++state.index;
        continue;
      } else if (isSimpleWhitespace(state)) {
        ++state.index;
      } else {
        consumeSimpleToken(state);
      }
      resetSimpleNotIfNeeded(state);
    }
  }

  private boolean isSimpleSubQueryStart(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == '('
        && (simpleFlags & SimpleQueryParser.PRECEDENCE_OPERATORS) != 0;
  }

  private boolean isSimpleSubQueryEnd(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == ')'
        && (simpleFlags & SimpleQueryParser.PRECEDENCE_OPERATORS) != 0;
  }

  private boolean isSimplePhraseStart(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == '"'
        && (simpleFlags & SimpleQueryParser.PHRASE_OPERATOR) != 0;
  }

  private boolean isSimpleAndOperator(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == '+'
        && (simpleFlags & SimpleQueryParser.AND_OPERATOR) != 0;
  }

  private boolean isSimpleOrOperator(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == '|'
        && (simpleFlags & SimpleQueryParser.OR_OPERATOR) != 0;
  }

  private boolean isSimpleNotOperator(SimpleSyntaxState state) {
    this.simpleParseState = state;
    return state.data[state.index] == '-'
        && (simpleFlags & SimpleQueryParser.NOT_OPERATOR) != 0;
  }

  private boolean isSimpleWhitespace(SimpleSyntaxState state) {
    this.simpleParseState = state;
    char current = currentSimpleChar();
    if ((simpleFlags & SimpleQueryParser.WHITESPACE_OPERATOR) == 0) {
      return false;
    }
    return current == ' ' || current == '\t' || current == '\n' || current == '\r';
  }

  private void consumeSimpleSubQuery(SimpleSyntaxState state) {
    this.simpleParseState = state;
    int start = ++state.index;
    int precedence = 1;
    boolean escaped = false;
    while (state.index < state.length) {
      if (!escaped) {
        if (isSimpleEscapeChar(state.data[state.index])) {
          escaped = true;
          ++state.index;
          continue;
        } else if (state.data[state.index] == '(') {
          ++precedence;
        } else if (state.data[state.index] == ')') {
          --precedence;
          if (precedence == 0) {
            break;
          }
        }
      }
      escaped = false;
      ++state.index;
    }
    if (state.index == state.length) {
      state.index = start;
    } else if (state.index == start) {
      state.currentOperation = null;
      ++state.index;
    } else {
      SimpleSyntaxState subState =
          new SimpleSyntaxState(state.data, state.buffer, start, state.index);
      parseSimpleSubQuery(subState);
      buildSimpleQueryTree(state, subState.top);
      ++state.index;
    }
  }

  private void consumeSimplePhrase(SimpleSyntaxState state) {
    this.simpleParseState = state;
    int start = ++state.index;
    int copied = 0;
    boolean escaped = false;
    boolean hasSlop = false;
    while (state.index < state.length) {
      if (!escaped) {
        if (isSimpleEscapeChar(state.data[state.index])) {
          escaped = true;
          ++state.index;
          continue;
        } else if (state.data[state.index] == '"') {
          if (state.length > (state.index + 1)
              && state.data[state.index + 1] == '~'
              && isSimpleNearEnabled()) {
            state.index++;
            if (state.length > (state.index + 1)) {
              hasSlop = true;
            }
            break;
          } else {
            break;
          }
        }
      }
      escaped = false;
      state.buffer[copied++] = state.data[state.index++];
    }
    if (state.index == state.length) {
      state.index = start;
    } else if (state.index == start) {
      state.currentOperation = null;
      ++state.index;
    } else {
      String phrase = new String(state.buffer, 0, copied);
      Query branch;
      if (hasSlop) {
        branch = buildSimplePhraseQuery(phrase, parseSimpleFuzziness(state));
      } else {
        branch = buildSimplePhraseQuery(phrase, 0);
      }
      buildSimpleQueryTree(state, branch);
      ++state.index;
    }
  }

  private void consumeSimpleToken(SimpleSyntaxState state) {
    this.simpleParseState = state;
    int copied = 0;
    boolean escaped = false;
    boolean prefix = false;
    boolean fuzzy = false;
    while (!simpleAtEnd()) {
      if (!escaped) {
        if (isSimpleEscapeChar(state.data[state.index])) {
          escaped = true;
          prefix = false;
          ++state.index;
          continue;
        } else if (simpleTokenFinished(state)) {
          break;
        } else if (isSimpleFuzzyChar(state.data[state.index], copied)) {
          fuzzy = true;
          break;
        }
        prefix = isSimplePrefixChar(state.data[state.index], copied);
      }
      escaped = false;
      state.buffer[copied++] = state.data[state.index++];
    }
    if (copied > 0) {
      final Query branch;
      if (fuzzy && (simpleFlags & SimpleQueryParser.FUZZY_OPERATOR) != 0) {
        String token = new String(state.buffer, 0, copied);
        int fuzziness = parseSimpleFuzziness(state);
        fuzziness = Math.min(fuzziness, LevenshteinAutomata.MAXIMUM_SUPPORTED_DISTANCE);
        if (fuzziness == 0) {
          branch = buildSimpleDefaultQuery(token);
        } else {
          branch = buildSimpleFuzzyQuery(token, fuzziness);
        }
      } else if (prefix) {
        String token = new String(state.buffer, 0, copied - 1);
        branch = buildSimplePrefixQuery(token);
      } else {
        String token = new String(state.buffer, 0, copied);
        branch = buildSimpleDefaultQuery(token);
      }
      buildSimpleQueryTree(state, branch);
    }
  }

  private BooleanQuery addSimpleClause(
      BooleanQuery bq, Query query, BooleanClause.Occur occur) {
    BooleanQuery.Builder newBq = new BooleanQuery.Builder();
    newBq.setMinimumNumberShouldMatch(bq.getMinimumNumberShouldMatch());
    for (BooleanClause clause : bq) {
      newBq.add(clause);
    }
    newBq.add(query, occur);
    return newBq.build();
  }

  private void buildSimpleQueryTree(SimpleSyntaxState state, Query branch) {
    this.simpleParseState = state;
    if (branch != null) {
      branch = applySimpleNot(state, branch);
      if (state.top == null) {
        state.top = branch;
      } else {
        if (state.currentOperation == null) {
          state.currentOperation = simpleDefaultOperator;
        }
        if (state.previousOperation != state.currentOperation) {
          BooleanQuery.Builder bq = new BooleanQuery.Builder();
          bq.add(state.top, state.currentOperation);
          state.top = bq.build();
        }
        state.top = addSimpleClause((BooleanQuery) state.top, branch, state.currentOperation);
        state.previousOperation = state.currentOperation;
      }
      state.currentOperation = null;
    }
  }

  private Query applySimpleNot(SimpleSyntaxState state, Query branch) {
    this.simpleParseState = state;
    if (state.not % 2 == 1) {
      BooleanQuery.Builder nq = new BooleanQuery.Builder();
      nq.add(branch, BooleanClause.Occur.MUST_NOT);
      nq.add(new MatchAllDocsQuery(), BooleanClause.Occur.SHOULD);
      return nq.build();
    }
    return branch;
  }

  private int parseSimpleFuzziness(SimpleSyntaxState state) {
    this.simpleParseState = state;
    char[] slopText = new char[state.length];
    int slopLength = 0;
    if (state.data[state.index] == '~') {
      while (state.index < state.length) {
        state.index++;
        if (state.index < state.length) {
          if (simpleTokenFinished(state)) {
            break;
          }
          slopText[slopLength] = state.data[state.index];
          slopLength++;
        }
      }
      int fuzziness = 0;
      try {
        String fuzzyString = new String(slopText, 0, slopLength);
        if ("".equals(fuzzyString)) {
          fuzziness = 2;
        } else {
          fuzziness = Integer.parseInt(fuzzyString);
        }
      } catch (@SuppressWarnings("unused") NumberFormatException e) {
        // swallow number format exceptions parsing fuzziness
      }
      if (fuzziness < 0) {
        fuzziness = 0;
      }
      return fuzziness;
    }
    return 0;
  }

  private boolean simpleTokenFinished(SimpleSyntaxState state) {
    this.simpleParseState = state;
    if ((state.data[state.index] == '"'
            && (simpleFlags & SimpleQueryParser.PHRASE_OPERATOR) != 0)
        || (state.data[state.index] == '|'
            && (simpleFlags & SimpleQueryParser.OR_OPERATOR) != 0)
        || (state.data[state.index] == '+'
            && (simpleFlags & SimpleQueryParser.AND_OPERATOR) != 0)
        || (state.data[state.index] == '('
            && (simpleFlags & SimpleQueryParser.PRECEDENCE_OPERATORS) != 0)
        || (state.data[state.index] == ')'
            && (simpleFlags & SimpleQueryParser.PRECEDENCE_OPERATORS) != 0)
        || ((state.data[state.index] == ' '
                || state.data[state.index] == '\t'
                || state.data[state.index] == '\n'
                || state.data[state.index] == '\r')
            && (simpleFlags & SimpleQueryParser.WHITESPACE_OPERATOR) != 0)) {
      return true;
    }
    return false;
  }

  public Query buildSimpleDefaultQuery(String text) {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    for (Map.Entry<String, Float> entry : simpleWeights.entrySet()) {
      Query q = weightedSimpleTerm(entry.getKey(), text, simpleDefaultOperator);
      if (q != null) {
        q = boostSimpleBranch(q, entry.getValue());
        bq.add(q, BooleanClause.Occur.SHOULD);
      }
    }
    return simplifySimpleBoolean(bq.build());
  }

  public Query buildSimpleFuzzyQuery(String text, int fuzziness) {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    for (Map.Entry<String, Float> entry : simpleWeights.entrySet()) {
      final String fieldName = entry.getKey();
      final BytesRef term = normalizeSimpleTerm(fieldName, text);
      Query q = new FuzzyQuery(new Term(fieldName, term), fuzziness);
      q = boostSimpleBranch(q, entry.getValue());
      bq.add(q, BooleanClause.Occur.SHOULD);
    }
    return simplifySimpleBoolean(bq.build());
  }

  public Query buildSimplePhraseQuery(String text, int slop) {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    for (Map.Entry<String, Float> entry : simpleWeights.entrySet()) {
      Query q = createPhraseQuery(entry.getKey(), text, slop);
      if (q != null) {
        q = boostSimpleBranch(q, entry.getValue());
        bq.add(q, BooleanClause.Occur.SHOULD);
      }
    }
    return simplifySimpleBoolean(bq.build());
  }

  public Query buildSimplePrefixQuery(String text) {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    for (Map.Entry<String, Float> entry : simpleWeights.entrySet()) {
      final String fieldName = entry.getKey();
      final BytesRef term = normalizeSimpleTerm(fieldName, text);
      Query q = new PrefixQuery(new Term(fieldName, term));
      q = boostSimpleBranch(q, entry.getValue());
      bq.add(q, BooleanClause.Occur.SHOULD);
    }
    return simplifySimpleBoolean(bq.build());
  }

  public Query simplifySimpleBoolean(BooleanQuery bq) {
    if (bq.clauses().isEmpty()) {
      return null;
    } else if (bq.clauses().size() == 1) {
      return bq.clauses().iterator().next().getQuery();
    } else {
      return bq;
    }
  }

  public Query rewriteComplexPhrase(
      String field,
      String phrasedQueryStringContents,
      int slopFactor,
      boolean inOrder,
      Query contents,
      IndexSearcher indexSearcher)
      throws IOException {
    this.phraseField = field;
    this.phraseQueryText = phrasedQueryStringContents;
    this.phraseSlop = slopFactor;
    this.phraseInOrder = inOrder;
    this.phraseContents = contents;
    return rewriteLoadedComplexPhrase(indexSearcher);
  }

  private Query rewriteLoadedComplexPhrase(IndexSearcher indexSearcher) throws IOException {
    final Query contents = this.phraseContents;
    if (isSimplePhraseTerm(contents)) {
      return contents;
    }
    if (!(contents instanceof BooleanQuery)) {
      throw unknownPhraseQueryType(contents);
    }
    BooleanQuery bq = (BooleanQuery) contents;
    SpanQuery[] allSpanClauses = new SpanQuery[bq.clauses().size()];
    int numNegatives = 0;
    int i = 0;
    for (BooleanClause clause : bq) {
      Query qc = rewritePhraseClause(indexSearcher, clause);
      if (isProhibitedClause(clause)) {
        numNegatives++;
      }
      qc = unwrapBoostedQuery(qc);
      allSpanClauses[i] = spanForPhraseClause(qc);
      i += 1;
    }
    this.analysisCount = numNegatives;
    if (numNegatives == 0) {
      return new SpanNearQuery(allSpanClauses, currentPhraseSlop(), phraseUsesInOrder());
    }
    return buildSpanNotFromMixedPhrase(bq, allSpanClauses, numNegatives);
  }

  private boolean isSimplePhraseTerm(Query contents) {
    this.analysisQuery = contents;
    this.analysisMode = 1;
    return contents instanceof TermQuery
        || contents instanceof MultiTermQuery
        || contents instanceof SynonymQuery;
  }

  private Query rewritePhraseClause(IndexSearcher indexSearcher, BooleanClause clause)
      throws IOException {
    this.analysisMode = 2;
    Query qc = clause.getQuery();
    return indexSearcher.rewrite(qc);
  }

  private Query unwrapBoostedQuery(Query qc) {
    this.analysisQuery = qc;
    while (qc instanceof BoostQuery) {
      qc = ((BoostQuery) qc).getQuery();
      this.analysisQuery = qc;
    }
    return qc;
  }

  private SpanQuery spanForPhraseClause(Query qc) {
    this.analysisQuery = qc;
    if (qc instanceof BooleanQuery || qc instanceof SynonymQuery) {
      return spanForBooleanOrSynonym(qc);
    }
    if (qc instanceof MatchNoDocsQuery) {
      return dummyPhraseSpan();
    }
    if (qc instanceof TermQuery) {
      TermQuery tq = (TermQuery) qc;
      return new SpanTermQuery(tq.getTerm());
    }
    throw unknownPhraseQueryType(qc);
  }

  private SpanQuery spanForBooleanOrSynonym(Query qc) {
    this.analysisMode = 3;
    ArrayList<SpanQuery> sc = new ArrayList<>();
    BooleanQuery booleanClause =
        qc instanceof BooleanQuery ? (BooleanQuery) qc : convertSynonym((SynonymQuery) qc);
    addComplexPhraseClause(sc, booleanClause);
    if (sc.size() > 0) {
      return sc.get(0);
    }
    return dummyPhraseSpan();
  }

  private IllegalArgumentException unknownPhraseQueryType(Query qc) {
    this.analysisQuery = qc;
    return new IllegalArgumentException(
        "Unknown query type \""
            + qc.getClass().getName()
            + "\" found in phrase query string \""
            + phraseQueryText
            + "\"");
  }

  private Query buildSpanNotFromMixedPhrase(
      BooleanQuery bq, SpanQuery[] allSpanClauses, int numNegatives) {
    this.analysisCount = numNegatives;
    ArrayList<SpanQuery> positiveClauses = new ArrayList<>();
    int i = 0;
    for (BooleanClause clause : bq) {
      if (!clause.getOccur().equals(BooleanClause.Occur.MUST_NOT)) {
        positiveClauses.add(allSpanClauses[i]);
      }
      i += 1;
    }
    SpanQuery[] includeClauses = positiveClauses.toArray(new SpanQuery[positiveClauses.size()]);
    SpanQuery include;
    if (includeClauses.length == 1) {
      include = includeClauses[0];
    } else {
      include = new SpanNearQuery(includeClauses, currentPhraseSlop() + numNegatives, phraseUsesInOrder());
    }
    SpanNearQuery exclude = new SpanNearQuery(allSpanClauses, currentPhraseSlop(), phraseUsesInOrder());
    return new SpanNotQuery(include, exclude);
  }

  private BooleanQuery convertSynonym(SynonymQuery qc) {
    this.analysisQuery = qc;
    BooleanQuery.Builder bqb = new BooleanQuery.Builder();
    for (Term t : qc.getTerms()) {
      bqb.add(new BooleanClause(new TermQuery(t), Occur.SHOULD));
    }
    return bqb.build();
  }

  private void addComplexPhraseClause(List<SpanQuery> spanClauses, BooleanQuery qc) {
    this.analysisQuery = qc;
    ArrayList<SpanQuery> ors = new ArrayList<>();
    ArrayList<SpanQuery> nots = new ArrayList<>();
    for (BooleanClause clause : qc) {
      Query childQuery = unwrapBoostedQuery(clause.getQuery());
      ArrayList<SpanQuery> chosenList = ors;
      if (clause.getOccur() == BooleanClause.Occur.MUST_NOT) {
        chosenList = nots;
      }
      if (childQuery instanceof TermQuery) {
        TermQuery tq = (TermQuery) childQuery;
        chosenList.add(new SpanTermQuery(tq.getTerm()));
      } else if (childQuery instanceof BooleanQuery) {
        addComplexPhraseClause(chosenList, (BooleanQuery) childQuery);
      } else if (childQuery instanceof MatchNoDocsQuery) {
        chosenList.add(dummyPhraseSpan());
      } else {
        throw new IllegalArgumentException("Unknown query type:" + childQuery.getClass().getName());
      }
    }
    if (ors.size() == 0) {
      return;
    }
    SpanOrQuery soq = new SpanOrQuery(copySpanClauses(ors));
    if (nots.size() == 0) {
      spanClauses.add(soq);
    } else {
      SpanOrQuery snqs = new SpanOrQuery(copySpanClauses(nots));
      spanClauses.add(new SpanNotQuery(soq, snqs));
    }
  }

  private SpanQuery dummyPhraseSpan() {
    this.analysisField = phraseField;
    return new SpanTermQuery(
        new Term(phraseField, "Dummy clause because no terms found - must match nothing"));
  }

  public Query buildBooleanFromXml(
      Element e, org.apache.lucene.queryparser.xml.QueryBuilder factory)
      throws ParserException {
    this.xmlFactory = factory;
    this.xmlMinShouldMatch = DOMUtils.getAttribute(e, "minimumNumberShouldMatch", 0);
    this.xmlBoost = DOMUtils.getAttribute(e, "boost", 1.0f);
    return assembleXmlBoolean(e);
  }

  private Query assembleXmlBoolean(Element e) throws ParserException {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    bq.setMinimumNumberShouldMatch(currentXmlMinimumShouldMatch());
    NodeList nl = e.getChildNodes();
    final int nlLen = nl.getLength();
    for (int i = 0; i < nlLen; i++) {
      Node node = nl.item(i);
      if (isXmlClauseNode(node)) {
        Element clauseElem = (Element) node;
        BooleanClause.Occur occurs = resolveXmlOccurs(clauseElem);
        Element clauseQuery = DOMUtils.getFirstChildOrFail(clauseElem);
        Query q = xmlChildQuery(clauseQuery);
        bq.add(new BooleanClause(q, occurs));
      }
    }
    return wrapParsedBoost(bq.build(), xmlBoost, false);
  }

  private BooleanClause.Occur resolveXmlOccurs(Element clauseElem) throws ParserException {
    this.analysisField = clauseElem.getAttribute("occurs");
    String occs = analysisField;
    if (occs == null || "should".equalsIgnoreCase(occs)) {
      return BooleanClause.Occur.SHOULD;
    } else if ("must".equalsIgnoreCase(occs)) {
      return BooleanClause.Occur.MUST;
    } else if ("mustNot".equalsIgnoreCase(occs)) {
      return BooleanClause.Occur.MUST_NOT;
    } else if ("filter".equals(occs)) {
      return BooleanClause.Occur.FILTER;
    }
    throw new ParserException("Invalid value for \"occurs\" attribute of clause:" + occs);
  }

  public Query wrapParsedBoost(Query query, float boost, boolean alwaysWrap) {
    this.xmlBoost = boost;
    if (query == null) {
      return null;
    }
    if (alwaysWrap || xmlBoostRequiresWrap()) {
      return new BoostQuery(query, xmlBoost);
    }
    return query;
  }

  public Query buildTermsFromXml(Element e, Analyzer analyzer) throws ParserException {
    this.xmlAnalyzer = analyzer;
    this.xmlMinShouldMatch = DOMUtils.getAttribute(e, "minimumNumberShouldMatch", 0);
    this.xmlBoost = DOMUtils.getAttribute(e, "boost", 1.0f);
    this.analysisField = DOMUtils.getAttributeWithInheritanceOrFail(e, "fieldName");
    String text = DOMUtils.getNonBlankTextOrFail(e);
    return assembleXmlTerms(text);
  }

  private Query assembleXmlTerms(String text) throws ParserException {
    BooleanQuery.Builder bq = new BooleanQuery.Builder();
    bq.setMinimumNumberShouldMatch(xmlMinShouldMatch);
    try (TokenStream ts = xmlAnalyzer.tokenStream(analysisField, text)) {
      TermToBytesRefAttribute termAtt = ts.addAttribute(TermToBytesRefAttribute.class);
      ts.reset();
      while (ts.incrementToken()) {
        Term term = new Term(analysisField, BytesRef.deepCopyOf(termAtt.getBytesRef()));
        bq.add(new BooleanClause(new TermQuery(term), BooleanClause.Occur.SHOULD));
      }
      ts.end();
    } catch (IOException ioe) {
      throw new RuntimeException("Error constructing terms from index:" + ioe);
    }
    return new BoostQuery(bq.build(), xmlBoost);
  }

  public Query buildTermFromXml(Element e) throws ParserException {
    this.analysisField = DOMUtils.getAttributeWithInheritanceOrFail(e, "fieldName");
    String value = DOMUtils.getNonBlankTextOrFail(e);
    this.xmlBoost = DOMUtils.getAttribute(e, "boost", 1.0f);
    Query tq = new TermQuery(new Term(analysisField, value));
    return wrapParsedBoost(tq, xmlBoost, false);
  }

  public Query buildRangeFromXml(Element e) throws ParserException {
    this.analysisField = DOMUtils.getAttributeWithInheritance(e, "fieldName");
    String lowerTerm = e.getAttribute("lowerTerm");
    String upperTerm = e.getAttribute("upperTerm");
    boolean includeLower = DOMUtils.getAttribute(e, "includeLower", true);
    boolean includeUpper = DOMUtils.getAttribute(e, "includeUpper", true);
    this.analysisMode = includeLower ? 1 : 0;
    this.analysisCount = includeUpper ? 1 : 0;
    return TermRangeQuery.newStringRange(
        analysisField, lowerTerm, upperTerm, includeLower, includeUpper);
  }

  public Query buildDisjunctionMaxFromXml(
      Element e, org.apache.lucene.queryparser.xml.QueryBuilder factory)
      throws ParserException {
    this.xmlFactory = factory;
    this.xmlTieBreaker = DOMUtils.getAttribute(e, "tieBreaker", 0.0f);
    this.xmlBoost = DOMUtils.getAttribute(e, "boost", 1.0f);
    return assembleXmlDisjunction(e);
  }

  private Query assembleXmlDisjunction(Element e) throws ParserException {
    List<Query> disjuncts = new ArrayList<>();
    NodeList nl = e.getChildNodes();
    final int nlLen = nl.getLength();
    for (int i = 0; i < nlLen; i++) {
      Node node = nl.item(i);
      if (isXmlElementNode(node)) {
        Query q = xmlChildQuery((Element) node);
        disjuncts.add(q);
      }
    }
    Query q = new DisjunctionMaxQuery(disjuncts, xmlTieBreaker);
    return wrapParsedBoost(q, xmlBoost, false);
  }

  private Query applyMappedBoost(Query q, String fieldName) {
    if (q == null || fields == null) {
      return null;
    }
    if (boosts != null) {
      Float boost = boosts.get(fieldName);
      if (boost != null) {
        q = new BoostQuery(q, boost.floatValue());
      }
    }
    return q;
  }



  private boolean simpleStateReady() {
    return simpleParseState != null
        && simpleParseState.data != null
        && simpleParseState.buffer != null;
  }

  private int simpleRemainingLength() {
    if (!simpleStateReady()) {
      return 0;
    }
    int remaining = simpleParseState.length - simpleParseState.index;
    return remaining < 0 ? 0 : remaining;
  }

  private boolean simpleAtEnd() {
    return simpleRemainingLength() == 0;
  }

  private void resetSimpleNotIfNeeded(SimpleSyntaxState state) {
    this.simpleParseState = state;
    if (state != null) {
      state.not = 0;
    }
  }

  private boolean simpleHasRemaining() {
    return simpleParseState != null && simpleParseState.index < simpleParseState.length;
  }

  private char currentSimpleChar() {
    if (!simpleHasRemaining()) {
      return 0;
    }
    return simpleParseState.data[simpleParseState.index];
  }

  private boolean isSimpleEscapeChar(char current) {
    return current == '\\' && (simpleFlags & SimpleQueryParser.ESCAPE_OPERATOR) != 0;
  }

  private boolean isSimplePrefixChar(char current, int copied) {
    return copied > 0 && current == '*' && (simpleFlags & SimpleQueryParser.PREFIX_OPERATOR) != 0;
  }

  private boolean isSimpleFuzzyChar(char current, int copied) {
    return copied > 0 && current == '~' && (simpleFlags & SimpleQueryParser.FUZZY_OPERATOR) != 0;
  }

  private boolean isSimpleNearEnabled() {
    return (simpleFlags & SimpleQueryParser.NEAR_OPERATOR) != 0;
  }

  private Query boostSimpleBranch(Query query, float boost) {
    if (query == null) {
      return null;
    }
    if (simpleWeights == null) {
      return query;
    }
    if (boost != 1f) {
      return new BoostQuery(query, boost);
    }
    return query;
  }

  private Query weightedSimpleTerm(String fieldName, String text, BooleanClause.Occur occur) {
    this.analysisField = fieldName;
    Query q = createBooleanQuery(fieldName, text, occur);
    return q;
  }

  private BytesRef normalizeSimpleTerm(String fieldName, String text) {
    this.analysisField = fieldName;
    if (simpleAnalyzer == null) {
      return new BytesRef(text);
    }
    return simpleAnalyzer.normalize(fieldName, text);
  }

  private boolean phraseUsesInOrder() {
    return phraseInOrder;
  }

  private int currentPhraseSlop() {
    return phraseSlop;
  }

  private boolean isProhibitedClause(BooleanClause clause) {
    this.analysisMode = 6;
    return clause != null && clause.getOccur().equals(BooleanClause.Occur.MUST_NOT);
  }

  private SpanQuery[] copySpanClauses(List<SpanQuery> clauses) {
    this.analysisCount = clauses.size();
    return clauses.toArray(new SpanQuery[clauses.size()]);
  }

  private boolean xmlBoostRequiresWrap() {
    return xmlBoost != 1f;
  }

  private int currentXmlMinimumShouldMatch() {
    return xmlMinShouldMatch;
  }

  private boolean isXmlClauseNode(Node node) {
    return node != null && "Clause".equals(node.getNodeName());
  }

  private boolean isXmlElementNode(Node node) {
    return node instanceof Element;
  }

  private Query xmlChildQuery(Element element) throws ParserException {
    if (xmlFactory == null) {
      throw new ParserException("Query factory is required");
    }
    return xmlFactory.getQuery(element);
  }

  static final class SimpleSyntaxState {
    final char[] data;
    final char[] buffer;
    int index;
    int length;
    BooleanClause.Occur currentOperation;
    BooleanClause.Occur previousOperation;
    int not;
    Query top;

    SimpleSyntaxState(char[] data, char[] buffer, int index, int length) {
      this.data = data;
      this.buffer = buffer;
      this.index = index;
      this.length = length;
    }
  }
}

